R=[('Dez anos atrás, ele sobreviveu à queda de um avião.', 1.0, 0.15), ('E sábado passado... se despediu do futebol nos braços da torcida.', 1.0, 0.3), ('Esse é o Alan Ruschel. Lateral-esquerdo, revelado no Juventude.', 1.05, 0.12), ('Em 2016, ele vivia um sonho: a pequena Chapecoense na final da Sul-Americana!', 1.05, 0.12), ('O último jogo antes da viagem? Contra o Palmeiras, no dia do título de 2016.', 1.05, 0.3), ('Na noite de 28 de novembro, o avião caiu perto de Medellín.', 0.95, 0.25), ('Setenta e uma pessoas morreram. Só seis sobreviveram... e o Alan era um deles.', 0.95, 0.3), ('Ele fraturou a coluna. Corria risco de ficar tetraplégico.', 1.0, 0.25), ('Oito meses depois... entrou no Camp Nou, contra o Barcelona!', 1.05, 0.12), ('Em novembro de 2017, voltou num jogo oficial, contra o Flamengo, aplaudido pelas duas torcidas!', 1.08, 0.12), ('Jogou mais nove anos.', 1.05, 0.12), ('E no último jogo, sábado, o Juventude venceu, subiu pra Série A... e ele saiu carregado!', 1.08, 0.3), ('Na despedida, ele escreveu: Obrigado, futebol. Eu faria tudo outra vez.', 0.95, 0.3), ('No dia 29, a tragédia completa dez anos. Deixa nos comentários uma homenagem pros guerreiros da Chape.', 1.02, 0.1)]
V=[('O Veiga vai voltar!', 1.1, 0.1), ('O América avisou o Palmeiras que não vai pagar a compra... e o camisa 23 volta pra casa em 2027!', 1.1, 0.15), ('Mas você conhece a história dele de verdade?', 1.08, 0.15), ('O avô dele era palmeirense fanático. Levou o filho ao estádio... e o filho levou o neto.', 1.05, 0.2), ('Um dia, o avô estava numa UTI. O Raphael se despediu, foi saindo... e o avô chamou ele de volta.', 1.0, 0.2), ('Se tiver oportunidade, jogue no Palmeiras.', 0.95, 0.25), ('Foi a última vez que eles se viram.', 0.95, 0.35), ('Em 2017, ele cumpriu a promessa!', 1.05, 0.12), ('Foram 378 jogos e 109 gols. O maior artilheiro do Palmeiras neste século!', 1.1, 0.12), ('Duas Libertadores, com gol na final de 2021!', 1.1, 0.2), ('Quando saiu, deixou uma carta no armário... pra abrir só quando voltasse.', 1.0, 0.25), ('Comenta aí: o que você acha que está escrito nessa carta?', 1.05, 0.1)]
A=[('Piquerez machucado... e agora?', 1.1, 0.1), ('Calma, palmeirense! Tem um garoto de 21 anos que você tá subestimando.', 1.12, 0.15), ('O Piquerez se lesionou na coxa no amistoso do Uruguai, e quem deve assumir a lateral esquerda é o Arthur.', 1.12, 0.12), ('Ele chegou ao Palmeiras com onze anos, no sub-11, e passou por todas as categorias.', 1.1, 0.1), ('A mãe levava ele de Guarulhos pro treino... e esperava no parque.', 1.05, 0.15), ('Na base, foi bicampeão brasileiro sub-20!', 1.1, 0.1), ('Estreou no profissional em janeiro, já é campeão paulista, e o Abel elogiou: ele dá passe, não cruzamento.', 1.12, 0.12), ('E olha os números: trinta e três jogos em 2026, sete na Libertadores. Isso é reserva?', 1.12, 0.15), ('Agora vem Flamengo no sábado... e a final da Libertadores no dia 28!', 1.1, 0.12), ('Comenta aí: o Arthur dá conta?', 1.08, 0.1)]
